<?php $plural=$domain==='career'?'careers':'bursaries';$title=$domain==='career'?'Career opportunities':'Bursary opportunities';?><div class="d-flex justify-content-between align-items-center mb-4"><div><h1><?=e($title)?></h1><p class="text-muted">Published opportunities currently accepting applications.</p></div><?php if(user()):?><a class="btn btn-outline-primary" href="<?=e(url('/'.$plural.'/applications'))?>">My applications</a><?php endif;?></div><form class="card card-body mb-4" method="get"><div class="row g-2"><div class="col-md-5"><input class="form-control" name="q" value="<?=e($filters['q']??'')?>" placeholder="Search opportunities"></div><?php if($domain==='career'):?><div class="col-md-3"><select class="form-select" name="profession_id"><option value="">All professions</option><?php foreach($professions as $p):?><option value="<?=e($p['id'])?>" <?=($filters['profession_id']??'')==(string)$p['id']?'selected':''?>><?=e($p['name'])?></option><?php endforeach;?></select></div><div class="col-md-3"><select class="form-select" name="province_id"><option value="">All provinces</option><?php foreach($provinces as $p):?><option value="<?=e($p['id'])?>" <?=($filters['province_id']??'')==(string)$p['id']?'selected':''?>><?=e($p['name'])?></option><?php endforeach;?></select></div><?php else:?><div class="col-md-3"><input class="form-control" name="field_of_study" value="<?=e($filters['field_of_study']??'')?>" placeholder="Field of study"></div><div class="col-md-3"><input class="form-control" name="study_level" value="<?=e($filters['study_level']??'')?>" placeholder="Study level"></div><?php endif;?><div class="col-md-1"><button class="btn btn-primary w-100">Go</button></div></div></form><?php if(!$opportunities):?><div class="alert alert-info">No open published opportunities match your filters.</div><?php endif;?><div class="row g-4"><?php foreach($opportunities as $o):?><div class="col-md-6"><article class="card h-100 shadow-sm"><div class="card-body"><span class="badge text-bg-success">Open</span><h2 class="h4 mt-2"><?=e($o['title'])?></h2><p class="text-muted"><?=e($domain==='career'?$o['organisation']:$o['provider'])?></p><p><?=e($domain==='career'?$o['summary']:$o['field_of_study'].' · '.$o['study_level'])?></p><p><strong>Closes:</strong> <?=e($o['closing_date'])?></p><a class="btn btn-outline-primary" href="<?=e(url('/'.$plural.'/'.$o['opportunity_reference']))?>">View details</a></div></article></div><?php endforeach;?></div>
